import express from 'express';
import { Parser } from 'expr-eval';

const app = express();
app.use(express.json());

/**
 * Safely evaluates a rule expression against a caller-supplied context.
 *
 * Uses expr-eval, which parses the expression into an AST and evaluates only
 * arithmetic, logical, comparison, and ternary operators — no host-language
 * code execution is possible.
 *
 * Supported expression syntax examples:
 *   ctx.amount > 100
 *   ctx.role == "admin" and ctx.active == true
 *   ctx.score >= 90 or ctx.override == true
 *
 * @param {string} expr  - The rule expression string from the request body.
 * @param {object} ctx   - The context object from the request body.
 * @returns {boolean}    - The result of evaluating the expression.
 * @throws               - If the expression is syntactically invalid.
 */
function evalRule(expr, ctx) {
  const parser = new Parser();
  const parsed = parser.parse(expr);
  const result = parsed.evaluate({ ctx });
  return Boolean(result);
}

/**
 * POST /check
 *
 * Request body:
 * {
 *   "rule":    string,  // expression to evaluate, e.g. "ctx.amount > 100"
 *   "context": object   // data available to the expression as `ctx`
 * }
 *
 * Successful response (200):
 * {
 *   "result": boolean   // whether the rule evaluated to true
 * }
 *
 * Error response (400):
 * {
 *   "error": string     // human-readable description of what went wrong
 * }
 */
app.post('/check', (req, res) => {
  const { rule, context } = req.body;

  if (typeof rule !== 'string' || rule.trim() === '') {
    return res
      .status(400)
      .json({ error: '`rule` must be a non-empty string.' });
  }

  if (context === undefined || context === null || typeof context !== 'object') {
