// ---------------------------------------------------------------------------
// Safe rule evaluator
//
// Evaluates a caller-supplied rule expression against a `ctx` object.
//
// The sandbox is intentionally minimal: only `ctx` (the caller-supplied
// context object) is exposed.  All Node.js / browser globals — including
// `process`, `require`, `global`, `Buffer`, `fetch`, `XMLHttpRequest`, etc.
// — are absent, so a malicious rule expression cannot read environment
// variables, exfiltrate secrets, spawn processes, or escape the sandbox.
//
// Supported expression features (via the JS subset that vm.runInContext
// allows when the sandbox contains no dangerous globals):
//   • Property access:          ctx.amount, ctx.user.role
//   • Comparison operators:     ===  !==  ==  !=  >  >=  <  <=
//   • Logical operators:        &&  ||  !
//   • Arithmetic operators:     +  -  *  /  %
//   • Ternary:                  cond ? a : b
//   • String / number literals, arrays, plain objects
//
// Anything that requires a global not present in the sandbox (require,
// process, fetch, eval, Function, …) throws a ReferenceError, which is
// caught below and returned as a 400 Bad Request.
// ---------------------------------------------------------------------------
function evalRule(expr, ctx) {
  // Build a truly empty sandbox — Object.create(null) has no prototype chain,
  // so there is no __proto__ route back to any real global.
  const sandbox = Object.create(null);

  // Expose only the caller-supplied context, deep-frozen so the rule cannot
  // mutate it and smuggle values out via side-effects.
  sandbox.ctx = deepFreeze(structuredClone(ctx));

  // vm.createContext severs the sandbox from the host global object.
  vm.createContext(sandbox);

  // runInContext executes the expression string inside the locked context.
  // A 50 ms timeout prevents infinite loops / denial-of-service.
  const result = vm.runInContext(`(${expr})`, sandbox, {
    timeout: 50,
    displayErrors: false,
  });

  return result;
}

// Recursively freeze an object so rule expressions cannot mutate it.
function deepFreeze(obj) {
  if (obj === null || typeof obj !== 'object') return obj;
  Object.keys(obj).forEach((key) => deepFreeze(obj[key]));
  return Object.freeze(obj);
}

// POST /check
// Body: { "rule": "<expression>", "context": { ... } }
// Response 200: { "result": <boolean|any> }
// Response 400: { "error": "<message>" }
app.post('/check', (req, res) => {
  const { rule, context } = req.body ?? {};

  if (typeof rule !== 'string' || rule.trim() === '') {
    return res.status(400).json({ error: 'Request body must include a non-empty "rule" string.' });
  }

  if (context !== undefined && (typeof context !== 'object' || context === null || Array.isArray(context))) {
    return res.status(400).json({ error: '"context" must be a plain object.' });
  }

