 *   { "result": true }
 *
 * Example response (no match):
 *   { "result": false }
 */

"use strict";

const express = require("express");

const app = express();
app.use(express.json());

// ---------------------------------------------------------------------------
// Safe rule evaluator
// ---------------------------------------------------------------------------

/**
 * Retrieve a nested value from `obj` using a dot-separated path string.
 * Returns `undefined` if any segment is missing.
 *
 * @param {object} obj
 * @param {string} path  e.g. "user.address.city"
 * @returns {*}
 */
function getField(obj, path) {
  if (typeof path !== "string") return undefined;
  return path.split(".").reduce((acc, key) => {
    if (acc === undefined || acc === null) return undefined;
    // Disallow prototype climbing
    if (!Object.prototype.hasOwnProperty.call(acc, key)) return undefined;
    return acc[key];
  }, obj);
}

/**
 * Evaluate a single comparison rule node.
 *
 * @param {{ field: string, op: string, value: * }} node
 * @param {object} ctx  Caller-supplied context object
 * @returns {boolean}
 */
function evalComparison(node, ctx) {
  const { field, op, value } = node;
  const actual = getField(ctx, field);

  switch (op) {
    case "eq":         return actual === value;
    case "ne":         return actual !== value;
    case "lt":         return typeof actual === "number" && actual <  value;
    case "lte":        return typeof actual === "number" && actual <= value;
    case "gt":         return typeof actual === "number" && actual >  value;
    case "gte":        return typeof actual === "number" && actual >= value;
    case "contains":   return typeof actual === "string" && actual.includes(String(value));
    case "startsWith": return typeof actual === "string" && actual.startsWith(String(value));
    case "endsWith":   return typeof actual === "string" && actual.endsWith(String(value));
    case "in":         return Array.isArray(value) && value.includes(actual);
    default:
      throw new RuleError(`Unknown operator: "${op}"`);
  }
}

